INSERT INTO exercises (id, wger_id, uuid, name, name_pt, description, category_id, source) VALUES
(1, 1962, '2f10d91f-6c12-471b-bb9e-80840a56ce01', 'Step Jack', NULL, 'The Step Jack is a low-impact plyometric-style move that provides cardiovascular benefits without the joint stress of jumping. It works the entire body, specifically targeting the legs, core, and shoulders. This move is ideal for beginners, individuals with joint sensitivities, or as a dynamic warm-up to gradually elevate the heart rate.
INSERT INTO exercises (id, wger_id, uuid, name, name_pt, description, category_id, source) VALUES
(501, 1584, '564dc73e-e8d4-4fd1-85ab-64dce4dd3ea0', 'March or jog in place', NULL, 'Low-impact cardiovascular exercise that simulates running without moving, ideal for warming up, improving endurance, or training in small spaces.', 15, 'WGER'),
(502, 1589, '505d6a28-1e24-4349-ab2b-49af3300e08e', 'Leg and hip stretch', NULL, 'Gentle movements to improve the flexibility of the lower body and release tension in the hips.', 9, 'WGER'),
(503, 1590, 'b48cd640-dd9f-4557-a4db-8cd33d5655a6', 'Arm and neck stretch', NULL, 'Relieves tension in the upper body, especially useful for people with office jobs or prolonged postures.', 10, 'WGER'),
(504, 1591, 'fae44c34-2e85-4d22-8fb8-7b14faf14719', 'Deep breathing (standing or seated)', NULL, 'A conscious breathing technique to improve oxygenation, reduce stress and connect with the present moment.', 11, 'WGER'),
(505, 1592, '7f942691-2a01-4675-9e3a-409105d5f2bf', 'Guided or free meditation', NULL, 'A mental mindfulness exercise that helps reduce anxiety, improve focus and enhance overall well-being.', 15, 'WGER'),
